-- O esquema do banco como a versão da Fase 7 o criou (Hibernate 7.4.13 + H2 2.4.240, ddl-auto=update),
-- extraído com SCRIPT NODATA de um banco gerado pela main em 2026-11-26. Repare nas colunas ENUM nativas:
-- é por elas que a Fase 8 converte as colunas de enum para texto (DA-40). Não reescreva à mão.
CREATE CACHED TABLE "PUBLIC"."JOGADORES"(
"ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
"CRIADO_EM" TIMESTAMP(6) WITH TIME ZONE NOT NULL,
"NOME" CHARACTER VARYING(20) NOT NULL,
"SENHA_HASH" CHARACTER VARYING(100) NOT NULL
);
ALTER TABLE "PUBLIC"."JOGADORES" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_8" PRIMARY KEY("ID");
CREATE CACHED TABLE "PUBLIC"."PARTIDAS"(
"ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
"DIFICULDADE" ENUM('DIFICIL', 'FACIL', 'MEDIO') NOT NULL,
"MODO" ENUM('CLASSICO', 'PILOTAGEM') DEFAULT 'CLASSICO' NOT NULL,
"MOVIMENTOS" INTEGER NOT NULL,
"PASSAGEIROS" INTEGER NOT NULL,
"PONTOS" INTEGER NOT NULL,
"REGISTRADA_EM" TIMESTAMP(6) WITH TIME ZONE NOT NULL,
"RESULTADO" ENUM('ABORTADA', 'DERROTA', 'VITORIA') NOT NULL,
"TEMPO_SEGUNDOS" BIGINT NOT NULL,
"JOGADOR_ID" BIGINT NOT NULL
);
ALTER TABLE "PUBLIC"."PARTIDAS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_7" PRIMARY KEY("ID");
CREATE INDEX "PUBLIC"."IX_PARTIDAS_JOGADOR" ON "PUBLIC"."PARTIDAS"("JOGADOR_ID" NULLS FIRST, "REGISTRADA_EM" NULLS FIRST);
CREATE INDEX "PUBLIC"."IX_PARTIDAS_RANKING" ON "PUBLIC"."PARTIDAS"("RESULTADO" NULLS FIRST, "PONTOS" NULLS FIRST);
ALTER TABLE "PUBLIC"."JOGADORES" ADD CONSTRAINT "PUBLIC"."UKIY8B6JYVYDO9P8F0S5HWTX0FG" UNIQUE NULLS DISTINCT ("NOME");
ALTER TABLE "PUBLIC"."PARTIDAS" ADD CONSTRAINT "PUBLIC"."FK9B5D3DDRQ6IFT3VU1MSPTJ5PJ" FOREIGN KEY("JOGADOR_ID") REFERENCES "PUBLIC"."JOGADORES"("ID") NOCHECK;

